#include <vector>
#include <unordered_map>
#include <algorithm>
using namespace std;

class Solution {
public:
    int minimumDistance(vector<int>& nums) {
        unordered_map<int, vector<int>> pos;
        for (int i = 0; i < (int)nums.size(); ++i) {
            pos[nums[i]].push_back(i);
        }
        int min_dist = 1e9;
        for (auto& [val, indices] : pos) {
            if (indices.size() >= 3) {
                for (size_t p = 0; p + 2 < indices.size(); ++p) {
                    min_dist = min(min_dist, indices[p + 2] - indices[p]);
                }
            }
        }
        return min_dist < 1e9 ? min_dist : -1;
    }
};

import java.util.*;

class Solution {
    public int minimumDistance(int[] nums) {
        Map<Integer, List<Integer>> pos = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            pos.computeIfAbsent(nums[i], k -> new ArrayList<>()).add(i);
        }
        int minDist = Integer.MAX_VALUE;
        for (List<Integer> indices : pos.values()) {
            if (indices.size() >= 3) {
                for (int p = 0; p + 2 < indices.size(); p++) {
                    minDist = Math.min(minDist, indices.get(p + 2) - indices.get(p));
                }
            }
        }
        return minDist != Integer.MAX_VALUE ? minDist : -1;
    }
}

var minimumDistance = function(nums) {
    const pos = new Map();
    for (let i = 0; i < nums.length; i++) {
        if (!pos.has(nums[i])) pos.set(nums[i], []);
        pos.get(nums[i]).push(i);
    }
    let minDist = Infinity;
    for (const indices of pos.values()) {
        if (indices.length >= 3) {
            for (let p = 0; p + 2 < indices.length; p++) {
                minDist = Math.min(minDist, indices[p + 2] - indices[p]);
            }
        }
    }
    return minDist !== Infinity ? minDist : -1;
};
